  const matches=bseApprovalRows_(bseTelegramApprovalSheet_(book)).map((row,index)=>({row:row,index:index})).filter(item=>String(item.row[17])==='CORRECTION_WAITING_INFO'&&String(item.row[7])===String(chatId)&&String(item.row[3])===String(userId)&&/^\d+$/.test(String(item.row[23]||''))&&!(queueRows||[]).some(queueRow=>String(queueRow[14])===String(item.row[0])));
