const bseTelegramOwnerNoticeBase_=bseTelegramOwnerNotice_;
bseTelegramOwnerNotice_=function(book,text){const message=String(text||''),match=message.match(/^Semakan TEST (BSE-TG-\d+)/m);if(!match||message.indexOf('Makluman TEST: disahkan oleh penghantar.')<0)return bseTelegramOwnerNoticeBase_(book,message);const reporter=bseTelegramReporterDisplayName_(book,match[1]),notice=message.replace('Makluman TEST: disahkan oleh penghantar.','Makluman TEST: disahkan oleh '+reporter+'.')+'\n'+bseTelegramOwnerDeleteInstruction_(match[1]);return bseTelegramOwnerNoticeBase_(book,notice);};

